corrected_code:
package profile

import (
	"net/http"
	"github.com/golang-jwt/jwt/v5"
	"github.com/labstack/echo/v4"
	"myapp/uploader"
)

type AvatarHandler struct {
	Uploader uploader.UploadService
}

func (h *AvatarHandler) InitiateAvatarUpload(c echo.Context) error {
	profileID := c.Param("profileID")
	token := c.Get("user").(*jwt.Token)
	claims := token.Claims.(jwt.MapClaims)
	authProfileID := claims["profile_id"].(string)

	if authProfileID != profileID {
		return c.JSON(http.StatusForbidden, echo.Map{"error": "Cannot initiate upload for another profile"})
	}

	uploadURL, err := h.Uploader.GeneratePresignedUploadURL(c.Request().Context(), profileID)
	if err != nil {
		return c.JSON(http.StatusInternalServerError, echo.Map{"error": err.Error()})
	}

	return c.JSON(http.StatusOK, echo.Map{"upload_url": uploadURL})
}
